for d,spec in D.items():
    dep=json.load(open(f'z/dep_{d}.json'))['metadata']
    m=copy.deepcopy(dep)
    for k in ('prereserve_doi','doi'): m.pop(k,None)
    if spec['title']: m['title']=spec['title']
    m['description']=spec['description']
    m['related_identifiers']=[r for r in m.get('related_identifiers',[]) if r['identifier'] not in spec['drop_related']]
    m['publication_date']='2026-11-23'
    json.dump({'metadata':m},open(f'new/meta_{d}.json','w'),ensure_ascii=False)
    import re
    t=re.sub('<[^>]+>',' ',m['description'])
    for w in ['PENDING','TODO','draft','probably','likely','expected','The user']:
        if re.search(w,t+m['title'],re.I): print('WARN',d,w)
    print(d,len(m['description']),m['title'][:80])
